const topoData={
star:{title:'Star Topology',text:'All devices connect to a central device such as a switch. One device sends to another through the central switch. It is easy to manage, but the central device is critical.',svg:`<g stroke="#256fce" stroke-width="5"><line x1="280" y1="165" x2="280" y2="55"/><line x1="280" y1="165" x2="420" y2="95"/><line x1="280" y1="165" x2="420" y2="235"/><line x1="280" y1="165" x2="140" y2="95"/><line x1="280" y1="165" x2="140" y2="235"/></g><g fill="#fff" stroke="#31a4d8" stroke-width="5"><circle cx="280" cy="165" r="36"/><circle cx="280" cy="55" r="25"/><circle cx="420" cy="95" r="25"/><circle cx="420" cy="235" r="25"/><circle cx="140" cy="95" r="25"/><circle cx="140" cy="235" r="25"/></g><text x="280" y="174" text-anchor="middle" font-size="24" font-weight="900">SW</text>`},
bus:{title:'Bus Topology',text:'All devices attach to one backbone cable. The sender places data onto the backbone, and the signal travels along the bus until it reaches the receiver node.',svg:`<line x1="80" y1="165" x2="480" y2="165" stroke="#256fce" stroke-width="8"/><g stroke="#256fce" stroke-width="4"><line x1="140" y1="165" x2="140" y2="95"/><line x1="240" y1="165" x2="240" y2="95"/><line x1="340" y1="165" x2="340" y2="235"/><line x1="430" y1="165" x2="430" y2="235"/></g><g fill="#fff" stroke="#31a4d8" stroke-width="5"><circle cx="140" cy="95" r="25"/><circle cx="240" cy="95" r="25"/><circle cx="340" cy="235" r="25"/><circle cx="430" cy="235" r="25"/></g>`},
ring:{title:'Ring Topology',text:'Devices form a closed loop. The packet moves from node to node around the ring in one direction until it reaches the receiver.',svg:`<circle cx="280" cy="165" r="115" fill="none" stroke="#256fce" stroke-width="5"/><g fill="#fff" stroke="#31a4d8" stroke-width="5"><circle cx="280" cy="50" r="26"/><circle cx="389" cy="130" r="26"/><circle cx="347" cy="260" r="26"/><circle cx="213" cy="260" r="26"/><circle cx="171" cy="130" r="26"/></g>`},
mesh:{title:'Mesh Topology',text:'Multiple links create many possible paths. In normal operation, the packet can use the direct link from the sender to the receiver.',svg:`<g stroke="#256fce" stroke-width="3" opacity=".85"><line x1="170" y1="90" x2="390" y2="90"/><line x1="170" y1="90" x2="130" y2="230"/><line x1="170" y1="90" x2="280" y2="275"/><line x1="170" y1="90" x2="430" y2="230"/><line x1="390" y1="90" x2="130" y2="230"/><line x1="390" y1="90" x2="280" y2="275"/><line x1="390" y1="90" x2="430" y2="230"/><line x1="130" y1="230" x2="280" y2="275"/><line x1="130" y1="230" x2="430" y2="230"/><line x1="280" y1="275" x2="430" y2="230"/></g><g fill="#fff" stroke="#31a4d8" stroke-width="5"><circle cx="170" cy="90" r="27"/><circle cx="390" cy="90" r="27"/><circle cx="130" cy="230" r="27"/><circle cx="280" cy="275" r="27"/><circle cx="430" cy="230" r="27"/></g>`},
tree:{title:'Tree Topology',text:'A tree has hierarchical levels. The packet travels on the branch lines from a higher-level node, through an intermediate branch, to the destination node.',svg:`<g stroke="#256fce" stroke-width="5"><line x1="280" y1="60" x2="280" y2="125"/><line x1="190" y1="125" x2="370" y2="125"/><line x1="190" y1="125" x2="130" y2="220"/><line x1="190" y1="125" x2="250" y2="220"/><line x1="370" y1="125" x2="310" y2="220"/><line x1="370" y1="125" x2="430" y2="220"/></g><g fill="#fff" stroke="#31a4d8" stroke-width="5"><circle cx="280" cy="60" r="27"/><circle cx="190" cy="125" r="25"/><circle cx="370" cy="125" r="25"/><circle cx="130" cy="220" r="23"/><circle cx="250" cy="220" r="23"/><circle cx="310" cy="220" r="23"/><circle cx="430" cy="220" r="23"/></g>`},
hybrid:{title:'Hybrid Topology',text:'A hybrid combines parts of multiple topologies. In this example, the packet moves through the designed main route from one side of the network to another.',svg:`<g stroke="#256fce" stroke-width="5"><line x1="160" y1="100" x2="260" y2="160"/><line x1="160" y1="220" x2="260" y2="160"/><line x1="260" y1="160" x2="410" y2="160"/><line x1="410" y1="160" x2="470" y2="90"/><line x1="410" y1="160" x2="470" y2="230"/><line x1="470" y1="90" x2="470" y2="230"/></g><g fill="#fff" stroke="#31a4d8" stroke-width="5"><circle cx="160" cy="100" r="25"/><circle cx="160" cy="220" r="25"/><circle cx="260" cy="160" r="30"/><circle cx="410" cy="160" r="30"/><circle cx="470" cy="90" r="25"/><circle cx="470" cy="230" r="25"/></g>`}
};

const topoExtra={
 star:{example:'Classroom lab, office LAN, home Wi‑Fi.',good:'Easy to install, manage, and expand.',limit:'Central device is a single point of failure.',failure:'Normal path: sender → central switch → receiver. If the central switch fails, the packet cannot cross the center, so the receiver becomes unreachable.',overlay:`<circle cx="280" cy="165" r="45" fill="rgba(255,224,87,.22)" stroke="#d85c62" stroke-width="8"/><text x="280" y="174" text-anchor="middle" font-size="28" fill="#d85c62" font-weight="900">✕</text><text x="280" y="306" text-anchor="middle" font-size="17" fill="#9a3036" font-weight="900">central switch failed: the sender cannot reach the receiver</text>`},
 bus:{example:'Older Ethernet bus networks; useful as a historical example.',good:'Uses less cable and is simple.',limit:'Backbone failure and collisions are major problems.',failure:'Normal path: sender node → backbone → receiver node. If the backbone breaks, the packet stops at the break, so nodes on opposite sides cannot communicate.',overlay:`<line x1="265" y1="165" x2="305" y2="165" stroke="#d85c62" stroke-width="12"/><text x="285" y="151" text-anchor="middle" font-size="30" fill="#d85c62" font-weight="900">✕</text><text x="280" y="306" text-anchor="middle" font-size="17" fill="#9a3036" font-weight="900">backbone break: the sender cannot reach the receiver on the other side</text>`},
 ring:{example:'Token Ring concepts; ring-based backbone designs.',good:'Orderly transmission and fewer collisions.',limit:'In a simple single ring, one break can stop the loop.',failure:'Normal path: sender → next node(s) → receiver. If one link in a simple single ring breaks, the path is interrupted and the packet cannot reach the receiver.',overlay:`<line x1="330" y1="72" x2="370" y2="102" stroke="#d85c62" stroke-width="12" stroke-linecap="round"/><text x="352" y="68" text-anchor="middle" font-size="30" fill="#d85c62" font-weight="900">✕</text><text x="280" y="306" text-anchor="middle" font-size="17" fill="#9a3036" font-weight="900">broken ring link: the selected path to the receiver is interrupted</text>`},
 mesh:{example:'Backbone networks, critical systems, data centers.',good:'High reliability and redundancy.',limit:'High cost and more complex management.',failure:'Normal path: sender → one chosen path → receiver. If that path fails, the packet can reroute through another path and still reach the receiver.',overlay:`<line x1="170" y1="90" x2="430" y2="230" stroke="#d85c62" stroke-width="10" stroke-linecap="round"/><text x="310" y="170" text-anchor="middle" font-size="30" fill="#d85c62" font-weight="900">✕</text><text x="280" y="306" text-anchor="middle" font-size="17" fill="#1f794f" font-weight="900">main link failed: traffic reroutes through a backup path</text>`},
 tree:{example:'Campus networks, department-based networks.',good:'Scales well for large organizations.',limit:'Upper-level or branch links can affect many child nodes.',failure:'Normal path: sender/root → branch node → receiver leaf. If the branch link breaks, that branch receiver becomes unreachable while other branches may still work.',overlay:`<line x1="190" y1="125" x2="130" y2="220" stroke="#d85c62" stroke-width="10" stroke-linecap="round"/><text x="146" y="162" text-anchor="middle" font-size="28" fill="#d85c62" font-weight="900">✕</text><text x="280" y="306" text-anchor="middle" font-size="17" fill="#9a3036" font-weight="900">branch link failed: this receiver cannot be reached through that branch</text>`},
 hybrid:{example:'Star LANs connected by mesh backbone; campus networks.',good:'Flexible and practical for real organizations.',limit:'Harder design, documentation, and troubleshooting.',failure:'Normal path: sender → main route → receiver. If a main link fails, a hybrid design may use a backup route to still reach the receiver.',overlay:`<line x1="260" y1="160" x2="410" y2="160" stroke="#d85c62" stroke-width="10" stroke-linecap="round"/><text x="334" y="152" text-anchor="middle" font-size="28" fill="#d85c62" font-weight="900">✕</text><text x="280" y="306" text-anchor="middle" font-size="17" fill="#1f794f" font-weight="900">main link failed: backup design keeps the sender and receiver connected</text>`}
};

